INSERT INTO debat (slug, theme_id, variable_id, chantier_id, proposition, nom_court, contexte, contexte_source_id, chiffre, chiffre_libelle, chiffre_source_id, ordre, etat, verifie_le, verifie_par) VALUES
('nouveaux-reacteurs', 6, (SELECT id FROM variable WHERE slug = 'reacteurs'), (SELECT id FROM chantier WHERE slug = 'nucleaire'),
INSERT INTO debat_argument (debat_id, sens, texte, porteur, source_id, ordre, etat) VALUES
((SELECT id FROM debat WHERE slug = 'nouveaux-reacteurs'), 'pour', 'Selon RTE, les scénarios qui incluent de nouveaux réacteurs sont les moins coûteux à l''horizon 2050, car ils réduisent les besoins de flexibilité et de réseau.', 'RTE, gestionnaire du réseau électrique', (SELECT id FROM source WHERE cle = 'lcp-2021-10-27-rte'), 1, 'valide'),
((SELECT id FROM debat WHERE slug = 'nouveaux-reacteurs'), 'pour', 'Renoncer au nucléaire, ou ralentir les renouvelables, ferait courir le risque de manquer d''électricité bas carbone et souveraine dès 2030, alors que l''électrification va accroître la consommation.', 'The Shift Project', (SELECT id FROM source WHERE cle = 'gazette-2026-05-19-shift'), 2, 'valide'),
((SELECT id FROM debat WHERE slug = 'nouveaux-reacteurs'), 'pour', 'Une électricité pilotable et peu émettrice, produite par une filière nationale qui maîtrise toute la chaîne, de l''uranium aux déchets, avec quelque 100 000 recrutements prévus en dix ans.', 'GIFEN, syndicat de la filière nucléaire', (SELECT id FROM source WHERE cle = 'gifen-2024-11-cndp'), 3, 'valide'),
((SELECT id FROM debat WHERE slug = 'nouveaux-reacteurs'), 'contre', 'Le coût des six premiers EPR2 est passé de 51,7 à 67,4 milliards d''euros lors de la réévaluation de 2023 ; la Cour des comptes demande de différer la décision tant que le financement n''est pas sécurisé.', 'Cour des comptes', (SELECT id FROM source WHERE cle = 'europe1-2025-01-14-epr'), 1, 'valide'),
((SELECT id FROM debat WHERE slug = 'nouveaux-reacteurs'), 'contre', 'Les nouveaux réacteurs arriveraient trop tard face à l''urgence climatique ; les renouvelables et la sobriété permettraient de décarboner plus vite et à moindre coût.', 'Association négaWatt', (SELECT id FROM source WHERE cle = 'politis-2023-05-negawatt'), 2, 'valide'),
((SELECT id FROM debat WHERE slug = 'nouveaux-reacteurs'), 'contre', 'Déchets à vie longue, capacité du stockage géologique Cigéo, protection des sites en cas de conflit : le débat public sur les nouveaux réacteurs a laissé ces questions ouvertes.', 'Commission nationale du débat public', (SELECT id FROM source WHERE cle = 'bdt-cndp-relance-nucleaire'), 3, 'valide');
INSERT INTO debat (slug, theme_id, variable_id, chantier_id, proposition, nom_court, contexte, contexte_source_id, chiffre, chiffre_libelle, chiffre_source_id, ordre, etat, verifie_le, verifie_par) VALUES
('thermiques-2035', 13, (SELECT id FROM variable WHERE slug = 'voitures-thermiques'), (SELECT id FROM chantier WHERE slug = 've'),
INSERT INTO debat_argument (debat_id, sens, texte, porteur, source_id, ordre, etat) VALUES
((SELECT id FROM debat WHERE slug = 'thermiques-2035'), 'pour', 'Sur sa durée de vie, une voiture électrique roulant en France a un impact carbone 2 à 3 fois inférieur à un modèle thermique comparable, si sa batterie reste sous 60 kWh.', 'Ademe, Agence de la transition écologique', (SELECT id FROM source WHERE cle = 'cde-2022-10-12-ademe'), 1, 'valide'),
((SELECT id FROM debat WHERE slug = 'thermiques-2035'), 'pour', 'Affaiblir l''échéance de 2035 brouille le signal donné aux industriels et retarde l''électrification européenne face aux constructeurs chinois, au détriment de la compétitivité et de l''emploi.', 'Transport & Environment, ONG européenne', (SELECT id FROM source WHERE cle = 'parlons-2026-10-16-auto'), 2, 'valide'),
((SELECT id FROM debat WHERE slug = 'thermiques-2035'), 'pour', 'La demande suit : les voitures électriques représentaient 29 % des voitures neuves vendues en France en mai 2026, contre 16 % un an plus tôt.', 'Chiffres de la Plateforme automobile et d''AAA Data', (SELECT id FROM source WHERE cle = 'pressecitron-2026-06-04-ve'), 3, 'valide'),
((SELECT id FROM debat WHERE slug = 'thermiques-2035'), 'contre', 'La filière a déjà perdu 40 000 emplois et pourrait en perdre 75 000 de plus d''ici 2035 ; les constructeurs demandent à pouvoir vendre encore hybrides et prolongateurs d''autonomie.', 'Plateforme automobile (PFA) et constructeurs', (SELECT id FROM source WHERE cle = 'automobiliste-2025-11-05-pfa'), 1, 'valide'),
((SELECT id FROM debat WHERE slug = 'thermiques-2035'), 'contre', 'Plus de souplesse permettrait de préserver la production automobile en Europe pendant sa transformation, avec une préférence européenne renforcée face à la concurrence chinoise.', 'Gouvernements français et allemand', (SELECT id FROM source WHERE cle = 'touteleurope-2026-10-16-auto'), 2, 'valide'),
((SELECT id FROM debat WHERE slug = 'thermiques-2035'), 'contre', 'Le tout-électrique suppose de multiplier les bornes, de 31 000 points publics en 2021 à 350 000 en dix ans, et expose à une dépendance à la Chine pour les batteries.', 'Fondation iFRAP', (SELECT id FROM source WHERE cle = 'ifrap-2022-06-thermiques'), 3, 'valide');
INSERT INTO debat (slug, theme_id, variable_id, chantier_id, proposition, nom_court, contexte, contexte_source_id, chiffre, chiffre_libelle, chiffre_source_id, ordre, etat, verifie_le, verifie_par) VALUES
('moratoire-centres-donnees', 14, (SELECT id FROM variable WHERE slug = 'centres-donnees'), (SELECT id FROM chantier WHERE slug = 'datacenters'),
INSERT INTO debat_argument (debat_id, sens, texte, porteur, source_id, ordre, etat) VALUES
((SELECT id FROM debat WHERE slug = 'moratoire-centres-donnees'), 'pour', 'Sans arbitrage, l''électricité bas carbone ira en priorité aux centres de données, au détriment d''usages à électrifier comme les transports : il faut contenir leur déploiement.', 'The Shift Project', (SELECT id FROM source WHERE cle = 'afp-2026-06-12-datacenters'), 1, 'valide'),
((SELECT id FROM debat WHERE slug = 'moratoire-centres-donnees'), 'pour', 'Des emprises jusqu''à 200 hectares, des craintes pour la ressource en eau, une chaleur rarement récupérée et des emplois très inférieurs aux promesses.', 'Élus locaux et députés porteurs d''une proposition de moratoire', (SELECT id FROM source WHERE cle = 'bdt-2026-10-13-datacenters'), 2, 'valide'),
((SELECT id FROM debat WHERE slug = 'moratoire-centres-donnees'), 'pour', 'Selon les auteurs du moratoire, 90 % des 15 GW demandés iraient à des acteurs non européens, surtout américains, ce qui renforcerait la dépendance numérique.', 'Députés écologistes et communistes', (SELECT id FROM source WHERE cle = 'bdt-2026-10-13-datacenters'), 3, 'valide'),
((SELECT id FROM debat WHERE slug = 'moratoire-centres-donnees'), 'contre', 'Une pause stricte risquerait de « déclasser » la France : mieux vaut ralentir, privilégier les sites les moins impactants et les financements européens.', 'Philippe Latombe, député, ancien président de la commission sur les dépendances numériques', (SELECT id FROM source WHERE cle = 'bdt-2026-10-13-datacenters'), 1, 'valide'),
((SELECT id FROM debat WHERE slug = 'moratoire-centres-donnees'), 'contre', 'Avec une électricité décarbonée à plus de 95 %, la France a intérêt à développer de nouveaux usages électriques ; EDF en a besoin comme relais de croissance.', 'France Datacenter, organisation professionnelle', (SELECT id FROM source WHERE cle = 'afp-2026-06-12-datacenters'), 2, 'valide'),
((SELECT id FROM debat WHERE slug = 'moratoire-centres-donnees'), 'contre', 'Pour les territoires d''accueil, ces projets apportent des investissements et un renforcement de la desserte électrique.', 'Élus des territoires d''accueil', (SELECT id FROM source WHERE cle = 'afp-2026-06-12-datacenters'), 3, 'valide');
INSERT INTO debat (slug, theme_id, variable_id, chantier_id, proposition, nom_court, contexte, contexte_source_id, chiffre, chiffre_libelle, chiffre_source_id, ordre, etat, verifie_le, verifie_par) VALUES
('encadrement-ia', 14, (SELECT id FROM variable WHERE slug = 'encadrement-ia'), NULL,
INSERT INTO debat_argument (debat_id, sens, texte, porteur, source_id, ordre, etat) VALUES
((SELECT id FROM debat WHERE slug = 'encadrement-ia'), 'pour', 'Les algorithmes publics peuvent introduire des biais et décider sans que l''usager le sache : il faut une supervision humaine réelle et un droit à l''explication.', 'Défenseure des droits', (SELECT id FROM source WHERE cle = 'bdt-2024-11-15-ddd'), 1, 'valide'),
((SELECT id FROM debat WHERE slug = 'encadrement-ia'), 'pour', 'Le compromis européen « repousse des protections clés » et affaiblit la transparence ; il installe un précédent dangereux pour tout le droit numérique.', 'EDRi, Access Now, ECNL et Amnesty International', (SELECT id FROM source WHERE cle = 'leto-2026-06-11-edri'), 2, 'valide'),
((SELECT id FROM debat WHERE slug = 'encadrement-ia'), 'pour', 'Les outils de recrutement peuvent reproduire les biais de leurs données ; les syndicats veulent encadrer l''IA au travail par le dialogue social.', 'Syndicats (projet DialIA), CNIL', (SELECT id FROM source WHERE cle = 'cms-ia-travail'), 3, 'valide'),
((SELECT id FROM debat WHERE slug = 'encadrement-ia'), 'contre', 'Les règles européennes sont déjà complexes et les surtranspositions nationales freinent le déploiement de l''IA en Europe ; une pause s''impose pour les usages à haut risque.', 'Mario Draghi, auteur du rapport sur la compétitivité européenne', (SELECT id FROM source WHERE cle = 'ppcland-2025-09-16-draghi'), 1, 'valide'),
((SELECT id FROM debat WHERE slug = 'encadrement-ia'), 'contre', 'Des règles floues créent une insécurité juridique : 45 entreprises européennes, dont Mistral AI, BNP Paribas et Carrefour, ont demandé un gel de deux ans.', 'Initiative EU AI Champions', (SELECT id FROM source WHERE cle = 'jdn-2025-07-04-stopclock'), 2, 'valide'),
((SELECT id FROM debat WHERE slug = 'encadrement-ia'), 'contre', 'Les entreprises ont obtenu des délais et des allègements pour se mettre en conformité, étendus en mai 2026 aux entreprises de moins de 750 salariés.', 'Industriels, selon l''accord européen de mai 2026', (SELECT id FROM source WHERE cle = 'bdt-2026-05-11-aiact'), 3, 'valide');
INSERT INTO debat (slug, theme_id, variable_id, chantier_id, proposition, nom_court, contexte, contexte_source_id, chiffre, chiffre_libelle, chiffre_source_id, ordre, etat, verifie_le, verifie_par) VALUES
('hebergement-souverain', 14, (SELECT id FROM variable WHERE slug = 'cloud-souverain'), NULL,
INSERT INTO debat_argument (debat_id, sens, texte, porteur, source_id, ordre, etat) VALUES
((SELECT id FROM debat WHERE slug = 'hebergement-souverain'), 'pour', 'Interrogé sous serment au Sénat, le directeur juridique de Microsoft France n''a pas pu garantir que des données de Français ne seraient jamais transmises aux autorités américaines.', 'Audition au Sénat, juin 2025', (SELECT id FROM source WHERE cle = 'gnt-2025-07-30-microsoft'), 1, 'valide'),
((SELECT id FROM debat WHERE slug = 'hebergement-souverain'), 'pour', 'Les fournisseurs européens sont passés de 29 % à 15 % du marché depuis 2017 : la souveraineté doit être un critère clair de la commande publique, « on l''est ou on ne l''est pas ».', 'CISPE, association de fournisseurs européens de cloud', (SELECT id FROM source WHERE cle = 'techradar-2025-10-28-cloud'), 2, 'valide'),
((SELECT id FROM debat WHERE slug = 'hebergement-souverain'), 'pour', 'Les données liées aux missions essentielles, comme la gestion de crise, la santé ou l''ordre public, doivent être protégées de la même façon par l''État et les collectivités.', 'Philippe Latombe, rapporteur de la proposition de loi', (SELECT id FROM source WHERE cle = 'bdt-2026-02-26-latombe'), 3, 'valide'),
((SELECT id FROM debat WHERE slug = 'hebergement-souverain'), 'contre', 'Microsoft indique n''avoir jamais transmis de données d''une entité publique européenne et s''engage par contrat à contester les demandes qu''il juge infondées.', 'Microsoft France', (SELECT id FROM source WHERE cle = 'gnt-2025-07-30-microsoft'), 1, 'valide'),
((SELECT id FROM debat WHERE slug = 'hebergement-souverain'), 'contre', 'Des offres hybrides qualifiées SecNumCloud, comme S3NS (Thales, technologies Google), assurent selon leurs promoteurs l''immunité aux lois extraterritoriales tout en donnant accès à des technologies américaines.', 'Thales et Google (S3NS)', (SELECT id FROM source WHERE cle = 'economiematin-2025-12-s3ns'), 2, 'valide'),
((SELECT id FROM debat WHERE slug = 'hebergement-souverain'), 'contre', 'L''offre qualifiée reste étroite, une dizaine de prestataires : le décret prévoit des dérogations d''un an, renouvelables, quand aucune offre n''est disponible.', 'Décret du 14 avril 2026', (SELECT id FROM source WHERE cle = 'bdt-2026-04-16-secnumcloud'), 3, 'valide');
INSERT INTO debat_position (debat_id, candidat_id, echelle, citation, source_id, statut_position, etat) VALUES
((SELECT id FROM debat WHERE slug = 'moratoire-centres-donnees'), (SELECT id FROM candidat WHERE slug = 'ruffin'), 1,
